// Persistent storage of used slugs across runs (n8n's static data API)
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.usedSlugs)) data.usedSlugs = [];

const queue = $input.first().json;
const next = queue.find((t) => !data.usedSlugs.includes(t.slug));

if (!next) {
  throw new Error('Topic queue exhausted. Add more topics to automation/topic-queue.json.');
}

data.usedSlugs.push(next.slug);
return [{ json: next }];

